    'targets.json':{desc:'Do alag targets, saaf retry budget aur Standard delivery DLQ ke saath',content:JSON.stringify(targets,null,2)},
    'schedule-target.json':{desc:'Scheduler ka execution-role raasta, retry aur delivery DLQ ke saath',content:JSON.stringify(scheduleTarget,null,2)},
    'refund-flow.asl.json':{desc:'Limit wala asli ASL shape: TEST worker Tasks, OutOfStock Catch aur refund retry',content:JSON.stringify(definition,null,2)},
    'event-entries.json':{desc:'PutEvents ka Detail JSON string hai; accept hona delivery se alag hai',content:JSON.stringify([{Source:'shop.orders',DetailType:'RefundRequested',Detail:JSON.stringify(detail)}],null,2)},
